cat > /tmp/fixlinks.py <<'EOF'
import re,subprocess,pathlib,os
PIN="013e7910d6fe8b9df9ba753bd68e2b6468bb4e51"
root=pathlib.Path.cwd()
skip={"docs/phase-6/fts-footprint/README.md"}
files=[f for f in subprocess.check_output(["git","ls-files","*.md"],text=True).split() if f.startswith(("docs/","README.md","REVIEW.md")) and f not in skip]
def exists_at_pin(rel):
    return subprocess.run(["git","cat-file","-e",f"{PIN}:{rel}"],capture_output=True).returncode==0
for f in files:
    p=pathlib.Path(f)
    if not p.exists(): continue
    s=p.read_text(); out=s
    def sub(m):
        t,a=m.group(1),m.group(2) or ""
        if t.startswith(("http","mailto:")) or (p.parent/t).exists(): return m.group(0)
        rel=os.path.normpath(os.path.join(os.path.dirname(f),t))
        if rel.endswith("BOOTSTRAP.md"): return m.group(0)
        if exists_at_pin(rel.rstrip("/")):
            kind="tree" if t.endswith("/") or (subprocess.run(["git","cat-file","-t",f"{PIN}:{rel}"],capture_output=True,text=True).stdout.strip()=="tree") else "blob"
            return f"](https://github.com/Kiy-K/oxide/{kind}/{PIN}/{rel}{a})"
        print("UNRESOLVED",f,t); return m.group(0)
    out=re.sub(r"\]\(([^)#\s]+)(#[^)]*)?\)",sub,s)
    if out!=s: p.write_text(out); print("fixed",f)
EOF
python3 /tmp/fixlinks.py; python3 /tmp/linkcheck.py
